    if i < 2: ax.tick_params(labelbottom=False)
ax.set_xlabel("frequency [Hz]")
fig.suptitle("Class-averaged amplitude spectra (each right-hand panel has its own amplitude scale)", x=0.01, ha="left", fontsize=11)
